names.example:
blueprint: build
permissions: [shell]

steps:
  build:
    do: shell
    with: { cmd: [make] }
    on_start:
      - emit: { topic: build.started }
    on_success:
      - do: log
        with: { message: "Built in ${self.duration_ms} ms." }
    on_finish:
      - emit: { topic: build.over, went: "${self.status}" }

blueprint: staged
permissions: [shell]

steps:
  migrate:
    when: ${ environment.name == "prod" }
    do: shell
    env: { API: "${environment.vars.api}" }
    with: { cmd: [./migrate] }

