blueprint: build
permissions: [shell]

steps:
  build:
    do: shell
    with: { cmd: [make] }
    watch:
      - after: 5m
        emit: { topic: build.slow }
      - every: 1m
        when: ${ self.duration_ms > 120000 }
        do: log
        with: { message: "Still building after ${self.duration_ms} ms." }
      - log: "^error"
        emit: { topic: build.error }
        fail: true

